def transform(grid):
    out = []
    for br in range(8):
        row = []
        for bc in range(8):
            counts = {}
            for r in range(br * 3, br * 3 + 3):
                for c in range(bc * 3, bc * 3 + 3):
                    v = grid[r][c]
                    if v != 5:
                        counts[v] = counts.get(v, 0) + 1
            row.append(max(counts, key=counts.get) if counts else 0)
        out.append(row)
    return out
